<?php require __DIR__.'/partials/header.php';require_login();$add=strtoupper(trim($_GET['add']??''));if($add&&preg_match('/^[A-Z0-9.\\-^=]{1,20}$/',$add)){q('INSERT IGNORE INTO watchlists(user_id,symbol) VALUES(?,?)',[user()['id'],$add]);}$rows=q('SELECT w.symbol,s.name FROM watchlists w LEFT JOIN stocks s ON s.symbol=w.symbol WHERE w.user_id=? ORDER BY w.created_at DESC',[user()['id']])->fetchAll();?><section class="section-head"><div><span class="eyebrow">PERSONAL RESEARCH</span><h1>Your watchlist</h1></div></section><div class="quick-grid"><?php foreach($rows as $r):?><a class="card stock-card" href="stock.php?symbol=<?=e($r['symbol'])?>"><b><?=e($r['symbol'])?></b><span><?=e($r['name']??'Open research')?> →</span></a><?php endforeach;if(!$rows):?><div class="card">Your watchlist is empty.</div><?php endif;?></div><?php require __DIR__.'/partials/footer.php'; ?>